CREATE TABLE categories (id UUID PRIMARY KEY, name VARCHAR(255) NOT NULL, search_keywords TEXT, special_requirements TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE articles (id UUID PRIMARY KEY, title TEXT NOT NULL, normalized_title_hash VARCHAR(64) NOT NULL, canonical_url TEXT NOT NULL, canonical_url_hash VARCHAR(64) NOT NULL, summary TEXT, published_at TIMESTAMPTZ, first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ, deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX ix_articles_canonical_url_hash ON articles (canonical_url_hash);
CREATE INDEX ix_articles_normalized_title_hash ON articles (normalized_title_hash);
CREATE TABLE ingestion_runs (id UUID PRIMARY KEY, trigger VARCHAR(32) NOT NULL, idempotency_key VARCHAR(255) NOT NULL, taipei_date DATE NOT NULL, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ, status VARCHAR(32) NOT NULL, candidate_count INTEGER NOT NULL DEFAULT 0, inserted_count INTEGER NOT NULL DEFAULT 0, duplicate_count INTEGER NOT NULL DEFAULT 0, error_count INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX ix_ingestion_runs_idempotency_key ON ingestion_runs (idempotency_key);
CREATE TABLE source_settings (id UUID PRIMARY KEY, category_id UUID NOT NULL REFERENCES categories(id), label VARCHAR(255) NOT NULL, website_input TEXT NOT NULL, normalized_host VARCHAR(255), kind VARCHAR(50) NOT NULL, position INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE category_articles (category_id UUID NOT NULL REFERENCES categories(id), article_id UUID NOT NULL REFERENCES articles(id), source_setting_id UUID NOT NULL REFERENCES source_settings(id), inserted_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (category_id, article_id));
CREATE UNIQUE INDEX ix_category_articles_category_article ON category_articles (category_id, article_id);
CREATE INDEX ix_category_articles_feed_cursor ON category_articles (category_id, inserted_at DESC, article_id DESC);
CREATE TABLE ingestion_attempts (id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES ingestion_runs(id), category_id UUID NOT NULL REFERENCES categories(id), source_setting_id UUID NOT NULL REFERENCES source_settings(id), status VARCHAR(32) NOT NULL, candidate_count INTEGER NOT NULL DEFAULT 0, inserted_count INTEGER NOT NULL DEFAULT 0, duplicate_count INTEGER NOT NULL DEFAULT 0, error_summary TEXT);
